local PCELL = {}
for k = 1, 16 do
  PCELL[k] = { 256, 256, ((k - 1) % 4) * 64 + 32, floor((k - 1) / 4) * 64 + 32, 64, 64 }
end

local ONDES = { { 2.5, FUSION }, { 2.56, LAVE }, { 2.66, VIVE } }
local GRADIENT = { { 0, FUSION }, { 0.2, FUSION }, { 0.33, LAVE }, { 0.5, VIVE }, { 0.62, BRAISE }, { 1, SOMBRE } }

local function frac(x)
  return x - floor(x)
end

local function borne(x, a, b)
  if x < a then return a end
  if x > b then return b end
  return x
end

local function lisse(a, b, x)
  x = borne((x - a) / (b - a), 0, 1)
  return x * x * (3 - 2 * x)
end

local function facile(x)
  x = borne(x, 0, 1)
  return 1 - (1 - x) ^ 3
end

local function melange(a, b, x)
  return a[1] + (b[1] - a[1]) * x, a[2] + (b[2] - a[2]) * x, a[3] + (b[3] - a[3]) * x
end

local function chaleurCouleur(h)
  if h < 0.25 then return melange(PIERRE_V, SOMBRE, borne(h / 0.25, 0, 1)) end
  if h < 0.5 then return melange(SOMBRE, BRAISE, (h - 0.25) / 0.25) end
  if h < 0.75 then return melange(BRAISE, VIVE, (h - 0.5) / 0.25) end
  if h < 1 then return melange(VIVE, LAVE, (h - 0.75) / 0.25) end
  return melange(LAVE, FUSION, borne((h - 1) / 0.4, 0, 1))
end

local function nombreCouleur(k)
  if k < 0.5 then return melange(OR, ORANGE, k / 0.5) end
  return melange(ORANGE, FUSION, (k - 0.5) / 0.5)
end

local function degrade(t)
  for i = 2, #GRADIENT do
    if t <= GRADIENT[i][1] then
      local a, b = GRADIENT[i - 1], GRADIENT[i]
      return melange(a[2], b[2], (t - a[1]) / (b[1] - a[1]))
    end
  end
  return SOMBRE[1], SOMBRE[2], SOMBRE[3]
end

local function chaleur(d, q, Lg)
  if q < 0 then return 0 end
  local h
  if q < 0.9 then
    h = (0.12 + 0.3 * exp(-((Lg - d) / 25) ^ 2) * (1 - lisse(0.6, 0.9, q))) * lisse(0, 0.1, q) + 0.48 * lisse(0.05, 0.9, q)
  elseif q < 1.9 then
    local env = lisse(0.9, 1.05, q) * (1 - lisse(1.7, 1.9, q))
    local ph = (q - 0.9) * 2.4 - d / 120
    h = 0.6 + 0.4 * lisse(0.9, 1.9, q) + 0.35 * env * (0.5 + 0.5 * cos(TAU * ph)) ^ 6
  elseif q < 4.4 then
    h = 1 + 0.06 * sin(9 * q + d / 30) * lisse(1.9, 2.1, q) * (1 - lisse(4.2, 4.4, q))
  else
    local u = borne((q - 4.4) / 1.8, 0, 1)
    local F = 330 - 400 * u
    h = 0.12 + 0.88 * (1 - lisse(F - 60, F, d) * lisse(4.4, 4.6, q)) + 0.45 * exp(-((d - (F - 25)) / 18) ^ 2) * lisse(4.4, 4.6, q) * (1 - lisse(6.0, 6.2, q))
  end
  return h + 0.6 * lisse(2.5, 2.53, q) * exp(-max(0, q - 2.53) / 0.35)
end

local function etat(E, t, q)
  E.t, E.q = t, q
  local A1 = 1.8 * lisse(0, 0.12, q) * exp(-max(0, q) / 0.55) * (1 - lisse(1.0, 1.5, q))
  local A4 = 3.6 * lisse(2.5, 2.52, q) * exp(-max(0, q - 2.52) / 0.12) * (1 - lisse(2.8, 2.95, q))
  E.sx = (A1 + A4) * sin(61 * q + 0.4)
  E.sy = (A1 + A4) * cos(47 * q + 1.1)
  E.flash = lisse(2.5, 2.52, q) * (1 - lisse(2.53, 2.58, q))
  E.eru = lisse(2.5, 2.53, q) * exp(-max(0, q - 2.53) / 0.4) * (1 - lisse(6.0, 6.9, q))
  E.respire = 0.75 + 0.25 * sin(TAU * t / 4)
  E.amb = 0.07 + 0.025 * sin(TAU * t / 4) + 0.22 * lisse(0.9, 1.9, q) * (1 - lisse(4.4, 6.2, q)) + 0.5 * E.eru
  E.ciel = lisse(2.9, 3.5, q) * (1 - lisse(4.4, 5.2, q))
  E.flam = lisse(3.05, 3.5, q) * (1 - lisse(4.4, 5.0, q))
  E.roche = lisse(3.0, 3.5, q) * (1 - lisse(5.4, 5.9, q))
  E.puitsA = lisse(1.9, 2.35, q) * (1 - lisse(6.2, 6.9, q))
  E.rw = min(70 * facile((q - 1.9) / 0.45), 70 * (1 - lisse(5.4, 6.2, q)))
  E.br = 1 - 0.65 * lisse(3.3, 3.7, q) * (1 - lisse(6.2, 6.9, q)) + 0.4 * E.eru
  E.bul = lisse(2.0, 2.3, q) * (1 - lisse(4.6, 5.6, q))
  E.bronze = lisse(1.0, 1.9, q) * (1 - lisse(4.6, 5.8, q)) + 0.5 * E.eru
  E.sillon = lisse(0.3, 1.2, q) * (1 - lisse(5.0, 6.2, q))
  E.hbed = 0.3 + 0.12 * E.respire + 0.75 * E.sillon + 0.35 * E.eru
  E.debord = lisse(1.5, 2.3, q) * (1 - lisse(5.0, 6.0, q))
  E.prog = lisse(1.5, 2.4, q)
  E.S = 1 + 0.06 * E.eru
  if q < 2.5 then
    E.avant = true
    E.numK = lisse(0.9, 1.9, q)
    E.numA = 1 - lisse(1.95, 2.45, q)
    E.numM = lisse(1.9, 2.45, q)
    E.numS = 1 + 0.35 * lisse(2.45, 2.5, q)
  else
    E.avant = false
    E.numK = q >= 3.3 and 1 - lisse(4.4, 6.2, q) or 1
    E.numA = lisse(3.3, 3.5, q)
    E.numM = 1 - lisse(3.0, 3.3, q)
    E.numS = 1 + 0.35 * (1 - lisse(3.65, 4.2, q))
  end
  local ub = borne((q - 2.5) / 0.35, 0, 1)
  local zb = 1 - 0.82 * ub
  E.fbD = lisse(2.85, 3.2, q)
  E.fbA = lisse(2.5, 2.53, q) * (1 - lisse(2.9, 3.2, q))
  E.fbR = (84 / zb) * (1 + 0.35 * E.fbD)
  E.fbH = 560 * E.fbD ^ 1.2
  E.vign = lisse(2.76, 2.86, q) * (1 - lisse(2.95, 3.2, q))
end

local function show(L, on)
  if L.s ~= on then
    L.s = on
    if on then L.t:Show() else L.t:Hide() end
  end
end

local function opacite(L, v)
  if v <= SEUIL then
    show(L, false)
    return false
  end
  if v > 1 then v = 1 end
  if L.a == nil or abs(L.a - v) >= 0.005 then
    L.a = v
    L.t:SetAlpha(v)
  end
  show(L, true)
  return true
end

local function teinte(L, r, g, b)
  r, g, b = r / 255, g / 255, b / 255
  if r > 1 then r = 1 end
  if g > 1 then g = 1 end
  if b > 1 then b = 1 end
  if r < 0 then r = 0 end
  if g < 0 then g = 0 end
  if b < 0 then b = 0 end
  if L.cr == nil or abs(L.cr - r) >= 0.0039 or abs(L.cg - g) >= 0.0039 or abs(L.cb - b) >= 0.0039 then
    L.cr, L.cg, L.cb = r, g, b
    L.t:SetVertexColor(r, g, b)
  end
end

local function pose(L, cx, cy, w, h)
  local gw, gh = w * L.K, h * L.K
  if L.w == nil or abs(L.w - gw) >= 0.01 or abs(L.h - gh) >= 0.01 then
    L.w, L.h = gw, gh
    L.t:SetSize(gw, gh)
  end
  local gx, gy = cx * L.K, -cy * L.K
  if L.x == nil or abs(L.x - gx) >= 0.01 or abs(L.y - gy) >= 0.01 then
    L.x, L.y = gx, gy
    L.t:SetPoint("CENTER", L.f, "TOPLEFT", gx, gy)
  end
end

local function coins(L, d, Lt, Wt, th, S, us, ka, cs)
  local lim = min(ANGLE_MAX, 0.2 / max(Lt, 1))
  local a = ka or d[5] / Lt
  local u0 = us or d[3] - d[5] / 2
  local o = cs or 0
  if L.ka ~= nil and abs(L.ka - Lt) < 0.01 and abs(L.kb - Wt) < 0.01 and abs(L.kth - th) < lim and abs(L.kS - S) < 0.01
    and abs(L.ku - u0) < 0.05 and abs(L.kk - a) < 0.002 and abs(L.ko - o) < 0.01 then
    return
  end
  L.ka, L.kb, L.kth, L.kS, L.ku, L.kk, L.ko = Lt, Wt, th, S, u0, a, o
  local c, s = cos(th), sin(th)
  local b = d[6] / Wt
  local h = S / 2
  local cv, tw, tt = d[4], d[1], d[2]
  local m = u0 + (Lt / 2 + o) * a
  local u1, v1 = (m + (-h * c - h * s) * a) / tw, (cv + (h * s - h * c) * b) / tt
  local u2, v2 = (m + (-h * c + h * s) * a) / tw, (cv + (h * s + h * c) * b) / tt
  local u3, v3 = (m + (h * c - h * s) * a) / tw, (cv + (-h * s - h * c) * b) / tt
  local u4, v4 = (m + (h * c + h * s) * a) / tw, (cv + (-h * s + h * c) * b) / tt
  local v = L.tv
  if v == nil or abs(v[1] - u1) > 1e-5 or abs(v[2] - v1) > 1e-5 or abs(v[3] - u2) > 1e-5 or abs(v[4] - v2) > 1e-5
    or abs(v[5] - u3) > 1e-5 or abs(v[6] - v3) > 1e-5 or abs(v[7] - u4) > 1e-5 or abs(v[8] - v4) > 1e-5 then
    L.tv = { u1, v1, u2, v2, u3, v3, u4, v4 }
    L.t:SetTexCoord(u1, v1, u2, v2, u3, v3, u4, v4)
  end
end

local function tracer(L, d, cx, cy, Lt, Wt, th, S, a, r, g, b)
  if a <= SEUIL or Lt < 0.05 or Wt < 0.05 then
    show(L, false)
    return
  end
  coins(L, d, Lt, Wt, th, S)
  pose(L, cx, cy, S, S)
  if r then teinte(L, r, g, b) end
  opacite(L, a)
end

local function tracerVeine(L, d, cx, cy, Lt, Wt, th, a, r, g, b, j0, j1)
  if a <= SEUIL or Lt < 0.05 or Wt < 0.05 then
    show(L, false)
    return
  end
  local e0, e1 = Wt, Wt
  if j0 then e0 = 0.5 * Wt end
  if j1 then e1 = 0.5 * Wt end
  local S = max(Lt + e0 + e1, 2 * Wt)
  local cs = (e1 - e0) / 2
  local us, ka
  if j0 and j1 then
    us, ka = d[3], 0
  else
    local u0, u1 = d[3] - d[5] / 2, d[3] + d[5] / 2
    if j1 then u1 = d[3] + 24 elseif j0 then u0 = d[3] - 24 end
    ka = (u1 - u0) / Lt
    if j0 or j1 then
      local ej = S / 2 - Lt / 2 + (j1 and cs or -cs)
      ka = min(ka, d[4] / max(ej, 0.01))
      if j1 then u0 = u1 - ka * Lt else u1 = u0 + ka * Lt end
    end
    us = u0
  end
  coins(L, d, Lt, Wt, th, S, us, ka, cs)
  pose(L, cx + cs * cos(th), cy + cs * sin(th), S, S)
  if r then teinte(L, r, g, b) end
  opacite(L, a)
end

local function disque(L, cx, cy, dm, a, r, g, b)
  if a <= SEUIL or dm < 0.1 then
    show(L, false)
    return
  end
  pose(L, cx, cy, dm, dm)
  if r then teinte(L, r, g, b) end
  opacite(L, a)
end

local function creer(frame, K, nom, mode, d)
  local t = frame:CreateTexture(nil, "ARTWORK")
  t:SetTexture(ART .. nom .. ".tga")
  t:SetBlendMode(mode)
  t:Hide()
  return { t = t, f = frame, K = K, s = false, d = d }
end

local function lot(frame, K, nom, mode, n, d)
  local liste = {}
  for i = 1, n do liste[i] = creer(frame, K, nom, mode, d) end
  return liste
end

local function cacher(liste)
  for _, L in pairs(liste) do show(L, false) end
end

local function cacherLave(R)
  cacher(R.veines)
  cacher(R.lueurs)
  cacher(R.joncs)
  cacher(R.fronts)
  if R.qv then cacher(R.qv) end
end

local function phaseBloc(vol, q)
  if q < vol.b then return 0 end
  if q < vol.b + vol.vie then return (q - vol.b) / vol.vie end
  if q < vol.rs then return 1 end
  return 1 - lisse(vol.rs, vol.re, q)
end

local function viderCaches(S)
  S.cacheC, S.cacheK = {}, {}
end

local function cadre(ring, niveau, G)
  local f = CreateFrame("Frame", nil, ring)
  f:SetSize(G, G)
  f:SetPoint("CENTER", ring, "CENTER", 0, 0)
  f:SetFrameLevel(ring:GetFrameLevel() + niveau)
  return f
end

local function rendreFond(S, E)
  local R = S.R
  disque(R.amb, CX, CY, 660, E.amb, VIVE[1], VIVE[2], VIVE[3])
  if E.ciel > 0.002 then
    disque(R.ciel, CX, 60, 800, 0.55 * E.ciel, CIEL[1], CIEL[2], CIEL[3])
  else
    show(R.ciel, false)
  end
  pose(R.socle, CX, CY, 256 * E.S, 256 * E.S)
end

local RESEAU

local function reseau()
  if RESEAU then return RESEAU end
  local N, A = JOINTS.noeuds, JOINTS.aretes
  local inc, nb = {}, {}
  for i = 1, #N do inc[i] = {} end
  for e = 1, #A do
    nb[e] = #A[e].p / 2
    local la, lb = inc[A[e].a], inc[A[e].b]
    la[#la + 1] = { e, 1 }
    lb[#lb + 1] = { e, -1 }
  end
  RESEAU = { inc = inc, nb = nb }
  return RESEAU
end

local function alea(graine)
  local x = floor(graine) % 2147483646 + 1
  local function suivant()
    x = (x * 16807) % 2147483647
    return x / 2147483647
  end
  local function etat(v)
    if v then x = v end
    return x
  end
  return suivant, etat
end

local function instantDepart(d)
  local f = 1 - d / (DMAX + 20)
  if f <= 0 then return 0.9 end
  return 0.9 * (1 - sqrt(f))
end

local function teteDe(q, e)
  local D = DMAX + 20
  local x = D * (1 - (1 - borne(q / 0.9, 0, 1)) ^ 2)
  local s = VIDAGE.decel
  local x0 = e - s
  if x0 >= D * 0.999 or x <= x0 then return x end
  local k = sqrt(1 - x0 / D)
  local tau = (q - 0.9 * (1 - k)) * (2.2222222 * D * k / (2 * s))
  if tau >= 1 then return e end
  return x0 + s * (1 - (1 - tau) ^ 2)
end

local function pointSur(pts, d)
  local lo, hi = 1, #pts
  if d <= pts[1][3] then return pts[1][1], pts[1][2] end
  if d >= pts[hi][3] then return pts[hi][1], pts[hi][2] end
  while hi - lo > 1 do
    local mid = floor((lo + hi) / 2)
    if pts[mid][3] <= d then lo = mid else hi = mid end
  end
  local a, b = pts[lo], pts[hi]
  local u = (d - a[3]) / max(b[3] - a[3], 0.000001)
  return a[1] + (b[1] - a[1]) * u, a[2] + (b[2] - a[2]) * u
end

local function densifier(xs, ys, pas)
  local sortie = { { xs[1], ys[1], 0 } }
  local s, suivant = 0, pas
  for i = 2, #xs do
    local sx, sy, ex, ey = xs[i - 1], ys[i - 1], xs[i], ys[i]
    local l = sqrt((ex - sx) ^ 2 + (ey - sy) ^ 2)
    if l > 1e-9 then
      while s + l >= suivant - 1e-9 do
        local u = (suivant - s) / l
        sortie[#sortie + 1] = { sx + (ex - sx) * u, sy + (ey - sy) * u, suivant }
        suivant = suivant + pas
      end
      s = s + l
    end
  end
  if sortie[#sortie][3] < s - 1e-6 then sortie[#sortie + 1] = { xs[#xs], ys[#ys], s } end
  return sortie
end

local function simplifier(pts, tol)
  local garde = { [1] = true, [#pts] = true }
  local pile = { { 1, #pts } }
  while #pile > 0 do
    local seg = table.remove(pile)
    local a, b = pts[seg[1]], pts[seg[2]]
    local dx, dy = b[1] - a[1], b[2] - a[2]
    local l = sqrt(dx * dx + dy * dy)
    local pire, ip = 0, nil
    for i = seg[1] + 1, seg[2] - 1 do
      local p = pts[i]
      local dist
      if l < 1e-9 then
        dist = sqrt((p[1] - a[1]) ^ 2 + (p[2] - a[2]) ^ 2)
      else
        dist = abs((p[1] - a[1]) * dy - (p[2] - a[2]) * dx) / l
      end
      if dist > pire then pire, ip = dist, i end
    end
    if ip and pire > tol then
      garde[ip] = true
      pile[#pile + 1] = { seg[1], ip }
      pile[#pile + 1] = { ip, seg[2] }
    end
  end
  local idx = {}
  for i in pairs(garde) do idx[#idx + 1] = i end
  table.sort(idx)
  return idx
end

local POIDS_LISSAGE = { 1, 2, 3, 2, 1 }

local function lisser(pts)
  local n = #pts
  if n < 5 then return pts end
  local sortie = { pts[1] }
  for i = 2, n - 1 do
    local r = min(2, i - 1, n - i)
    local sx, sy, sw = 0, 0, 0
    for k = -r, r do
      local w = POIDS_LISSAGE[3 + k]
      sx, sy, sw = sx + w * pts[i + k][1], sy + w * pts[i + k][2], sw + w
    end
    sortie[i] = { sx / sw, sy / sw, pts[i][3] }
  end
  sortie[n] = pts[n]
  return sortie
end

local function segmenter(coulees, tol)
  local segs = {}
  for c = 1, #coulees do
    local pts = lisser(coulees[c].pts)
    if #pts >= 2 then
      local idx = simplifier(pts, tol)
      for j = 2, #idx do
        local a, b = pts[idx[j - 1]], pts[idx[j]]
        segs[#segs + 1] = { x0 = a[1], y0 = a[2], x1 = b[1], y1 = b[2], d0 = a[3], d1 = b[3], b = coulees[c].branche, f = c }
      end
    end
  end
  return segs
end

local function tracerCoulees(S, m, W, cx, cy)
  local J = JOINTS
  local A, N = J.aretes, J.noeuds
  local res = reseau()
  local nb, inc = res.nb, res.inc
  local tp = J.taille
  local K = W / DIAMETRE
  local ts = m.tile / tp
  local pxs = ts / K
  local tex = 1 / pxs
  local ux, uy = (cx - m.left) / ts - 0.5, (m.top - cy) / ts - 0.5
  local rim = RAYON * tex
  local rstop = RSTOP * tex
  local dmain = DMAX * tex
  local tol = J.largeur / 2
  local rnd = alea(S.graine or GRAINE)

  local function rel(e, k, ox, oy)
    local p = A[e].p
    return p[2 * k - 1] + tp * ox - ux, p[2 * k] + tp * oy - uy
  end

  local function rayon(e, k, ox, oy)
    local x, y = rel(e, k, ox, oy)
    return sqrt(x * x + y * y)
  end

  local lox, hix = floor((ux - rim - 60) / tp), floor((ux + rim + 60) / tp)
  local loy, hiy = floor((uy - rim - 60) / tp), floor((uy + rim + 60) / tp)
  local function candidats(tolc)
    local lst = {}
    for e = 1, #A do
      for ox = lox, hix do
        for oy = loy, hiy do
          local bk, bd = nil, 1e9
          for k = 1, nb[e] do
            local dd = abs(rayon(e, k, ox, oy) - rim)
            if dd < bd then bd, bk = dd, k end
          end
          if bd <= tolc then
            local x, y = rel(e, bk, ox, oy)
            lst[#lst + 1] = { atan2(y, x) % TAU, e, bk, ox, oy, sqrt(x * x + y * y) }
          end
        end
      end
    end
    table.sort(lst, function(p, q) return p[1] < q[1] end)
    return lst
  end
  local utilise, reserve, file, sorties = {}, {}, {}, {}
  local function cle(e, ox, oy) return e .. ":" .. ox .. ":" .. oy end
  local function prendre(e, ox, oy)
    utilise[cle(e, ox, oy)] = true
  end
  local function ecartAngle(a, b)
    local d = abs(a - b) % TAU
    return d > PI and TAU - d or d
  end
  local function sensSortant(c)
    local e, k, ox, oy, r0 = c[2], c[3], c[4], c[5], c[6]
    local meilleur, sens = 0, nil
    for _, s in ipairs({ 1, -1 }) do
      local fin = s == 1 and nb[e] or 1
      local kk, dd = k, 0
      local px, py = rel(e, k, ox, oy)
      while kk ~= fin and dd < 16 do
        kk = kk + s
        local qx, qy = rel(e, kk, ox, oy)
        dd = dd + sqrt((qx - px) ^ 2 + (qy - py) ^ 2)
        px, py = qx, qy
      end
      local gain = sqrt(px * px + py * py) - r0
      if gain > meilleur then meilleur, sens = gain, s end
    end
    return sens
  end

  local function marcher(w)
    local e, s, k, ox, oy = w.e, w.s, w.k, w.ox, w.oy
    local x, y = rel(e, k, ox, oy)
    local xs, ys = { x }, { y }
    local d, rmax = w.d0, w.r0
    local fini = false
    prendre(e, ox, oy)
    while not fini do
      local dernier = s == 1 and nb[e] or 1
      while k ~= dernier do
        k = k + s
        local nx, ny = rel(e, k, ox, oy)
        local r = sqrt(nx * nx + ny * ny)
        if r < rmax - tol * 0.9 then
          fini = true
          break
        end
        local l = sqrt((nx - x) ^ 2 + (ny - y) ^ 2)
        if d + l >= w.lim then
          local u = (w.lim - d) / max(l, 1e-9)
          nx, ny = x + (nx - x) * u, y + (ny - y) * u
          d = w.lim
          fini = true
        else
          d = d + l
        end
        x, y = nx, ny
        xs[#xs + 1], ys[#ys + 1] = x, y
        if r > rmax then rmax = r end
        if r >= rstop then fini = true end
        if fini then break end
      end
      if fini then break end
      local noeud = s == 1 and A[e].b or A[e].a
      local rc = sqrt(x * x + y * y)
      local sources = { { noeud, ox, oy } }
      local jum = J.jumelles[noeud]
      if jum then
        sources[2] = { jum, ox + floor((N[noeud][1] - N[jum][1]) / tp + 0.5), oy + floor((N[noeud][2] - N[jum][2]) / tp + 0.5) }
      end
      local valides = {}
      for _, src in ipairs(sources) do
        for _, en in ipairs(inc[src[1]]) do
          local e2, s2 = en[1], en[2]
          local ck2 = cle(e2, src[2], src[3])
          if not utilise[ck2] and not reserve[ck2] then
            local k2 = s2 == 1 and 1 or nb[e2]
            local fin2 = s2 == 1 and nb[e2] or 1
            local rm, ok = rmax, true
            local kk = k2
            while true do
              local r = rayon(e2, kk, src[2], src[3])
              if r < rm - tol * 0.9 then
                ok = false
                break
              end
              if r > rm then rm = r end
              if kk == fin2 then break end
              kk = kk + s2
            end
            local gain = rayon(e2, fin2, src[2], src[3]) - rc
            if ok and gain > 0.5 then
              valides[#valides + 1] = { e = e2, s = s2, k = k2, ox = src[2], oy = src[3], poids = (gain + 3) ^ 6 }
            end
          end
        end
      end
      if #valides == 0 then break end
      local function tirer()
        local somme = 0
        for i = 1, #valides do somme = somme + valides[i].poids end
        local t = rnd() * somme
        for i = 1, #valides do
          t = t - valides[i].poids
          if t <= 0 or i == #valides then return table.remove(valides, i) end
        end
      end
      local choisi = tirer()
      if #valides >= 1 and #file < MAXC and rnd() < PBRANCHE then
        local autre = tirer()
        prendre(autre.e, autre.ox, autre.oy)
        file[#file + 1] = { e = autre.e, s = autre.s, k = autre.k, ox = autre.ox, oy = autre.oy, d0 = d, lim = min(dmain, d + BRANCHE * tex * (0.6 + 0.8 * rnd())), r0 = rmax, branche = true, parent = w }
      end
      prendre(choisi.e, choisi.ox, choisi.oy)
      e, s, k, ox, oy = choisi.e, choisi.s, choisi.k, choisi.ox, choisi.oy
    end
    w.xs, w.ys, w.dfin = xs, ys, d
  end

  local mains, branches = {}, {}
  local depart = {}
  for _, tolc in ipairs(TOLDEP) do
    depart = {}
    for _, c in ipairs(candidats(tolc)) do
      local sens = sensSortant(c)
      if sens then depart[#depart + 1] = { c = c, sens = sens } end
    end
    if #depart >= MINDEP then break end
  end
  for _, dp in ipairs(depart) do
    reserve[cle(dp.c[2], dp.c[4], dp.c[5])] = true
  end
  for _, dp in ipairs(depart) do
    local c = dp.c
    local w = { e = c[2], s = dp.sens, k = c[3], ox = c[4], oy = c[5], d0 = 0, lim = dmain, r0 = c[6], branche = false }
    marcher(w)
    if #w.xs > 1 then mains[#mains + 1] = w end
  end
  local qi = 1
  while qi <= #file do
    marcher(file[qi])
    branches[#branches + 1] = file[qi]
    qi = qi + 1
  end
  local ordre = {}
  for _, w in ipairs(mains) do ordre[#ordre + 1] = w end
  for _, w in ipairs(branches) do ordre[#ordre + 1] = w end
  for i, w in ipairs(ordre) do w.num = i end
  for i, w in ipairs(ordre) do
    sorties[i] = { xs = w.xs, ys = w.ys, d0 = w.d0, branche = w.branche, parent = w.parent and w.parent.num }
  end

  local pas = PAS_PTS / ts
  local coulees = {}
  for i = 1, #sorties do
    local o = sorties[i]
    local pts = densifier(o.xs, o.ys, pas)
    for j = 1, #pts do
      local p = pts[j]
      pts[j] = { CX + p[1] * pxs, CY + p[2] * pxs, (o.d0 + p[3]) * pxs }
    end
    local dd0, dd1 = pts[1][3], pts[#pts][3]
    local depart = instantDepart(dd0)
    coulees[i] = { pts = pts, depart = depart, vitesse = (DMAX - dd0) * K / max(instantDepart(DMAX) - depart, 0.001), fin = DUREE, branche = o.branche, parent = o.parent }
  end
  return coulees
end

local function actualiserTrace(S, definitif)
  local B = EbonAPI.Bricks
  local ring = S.ring
  local posee = JOINTS and B and B.mosaic and ring
  local m = posee and B.mosaic(ring)
  local cx, cy, W
  if posee then
    cx, cy = ring:GetCenter()
    W = ring:GetWidth()
    if not m and cx and cy then
      local es = ring:GetEffectiveScale() or 1
      m = B.mosaic(cx * es, cy * es, es)
      if not m and definitif and W and W > 0 and not S.signalee and EbonAPI.Catch and EbonAPI.Catch.report then
        S.signalee = true
        EbonAPI.Catch.report("EbonAPI-Skin-Magmathar:Prestige:mosaique-du-fond-introuvable", "EbonAPI-Skin-Magmathar")
      end
    end
    if not (m and m.tile and m.tile > 0) then cx, cy, W = nil, nil, nil end
  end
  local cle
  if cx and cy and W and W > 0 then
    cle = string.format("%d:%d:%d:%d", floor(cx - m.left + 0.5), floor(m.top - cy + 0.5), floor(m.tile + 0.5), floor(W + 0.5))
  else
    cle = "repli"
  end
  if S.cleTrace == cle then return end
  S.cleTrace = cle
  local R = S.R
  cacherLave(R)
  S.segs, S.coulees, S.bornes, S.lignes = nil, nil, nil, nil
  R.ang = R.angRepli
  if cle == "repli" then return end
  S.nTrace = (S.nTrace or 0) + 1
  local ts = m.tile / JOINTS.taille
  S.corps = 0.8 * JOINTS.largeur * ts / (W / DIAMETRE)
  local coulees = tracerCoulees(S, m, W, cx, cy)
  local tol = 0.5 * m.tile / JOINTS.taille / (W / DIAMETRE)
  local segs = segmenter(coulees, tol)
  for _ = 1, 10 do
    if #segs <= POOL then break end
    tol = tol * 1.4
    segs = segmenter(coulees, tol)
  end
  if #segs == 0 or #segs > POOL then return end
  local ang = {}
  for i = 1, #segs do
    local g = segs[i]
    ang[i] = atan2(g.y1 - g.y0, g.x1 - g.x0)
    g.j0 = i > 1 and segs[i - 1].f == g.f
    g.j1 = i < #segs and segs[i + 1].f == g.f
  end
  local bornes, lignes, vide = {}, {}, 0
  for f = 1, #coulees do
    local lp = lisser(coulees[f].pts)
    if #lp >= 2 then
      local de = lp[#lp][3]
      bornes[f] = { lp[1][3], de, coulees[f].branche }
      lignes[f] = lp
      vide = max(vide, teteDe(0.9, de))
    end
  end
  R.qv = R.qv or {}
  local cadreLave, echelle = R.veines[1].f, S.K
  for i = #R.qv + 1, #coulees * 2 * VIDAGE.tranches do R.qv[i] = creer(cadreLave, echelle, "veine", "BLEND", nil) end
  S.segs, S.coulees, S.bornes, S.lignes, S.vide = segs, coulees, bornes, lignes, vide
  R.ang = ang
end

local function veinesRepli(S, E)
  local R, q = S.R, E.q
  local Lg = 0
  if q >= 0 then Lg = (DMAX + 20) * (1 - (1 - borne(q / 0.9, 0, 1)) ^ 2) end
  local vis = 1 - lisse(6.2, 6.95, q)
  if Lg <= 0 or vis <= 0.002 then
    cacher(R.veines)
    cacher(R.lueurs)
    return
  end
  local sg = 0.9 + 0.5 * lisse(0, 0.9, q)
  local g3 = 3.8 * lisse(0.9, 1.9, q)
  local segs = S.segs or SEGS
  for i = 1, #segs do
    local g = segs[i]
    local V, G = R.veines[i], not g.b and R.lueurs[i] or nil
    if g.d0 >= Lg then
      show(V, false)
      if G then show(G, false) end
    else
      local fr = borne((Lg - g.d0) / (g.d1 - g.d0), 0, 1)
      local dm = (g.d0 + g.d1) / 2
      local h = chaleur(dm, q, Lg)
      local w = (sg + g3 * min(1.3, h)) * (1 - 0.45 * dm / DMAX) * (g.b and 0.6 or 1)
      local dx, dy = (g.x1 - g.x0) * fr, (g.y1 - g.y0) * fr
      local len = sqrt(dx * dx + dy * dy)
      local mx, my = g.x0 + dx / 2, g.y0 + dy / 2
      local wd = w + 1.6
      local ch = h < 1 and 0.75 * h or 0.75 + (h - 1)
      local r, gg, b = chaleurCouleur(ch)
      tracer(V, TXVEINE, mx, my, len + wd, wd, R.ang[i], len + 2 * wd, vis, r, gg, b)
      if G then
        if h > 0.3 then
          local mh = min(1, h)
          local r2, g2, b2 = chaleurCouleur(0.75 * mh)
          tracer(G, TXVLUEUR, mx, my, len + 3.5 * w, 3.5 * w, R.ang[i], len + 7 * w, 0.2 * mh * vis, r2, g2, b2)
        else
          show(G, false)
        end
      end
    end
  end
end

local function couleurLave(age, duree)
  local u = borne(age / duree, 0, 1)
  local r, g, b
  if u < 0.5 then r, g, b = melange(LAVE, VIVE, u / 0.5)
  elseif u < 0.75 then r, g, b = melange(VIVE, BRAISE, (u - 0.5) / 0.25)
  else r, g, b = melange(BRAISE, SOMBRE, (u - 0.75) / 0.25) end
  return r / 255, g / 255, b / 255, 1 - lisse(0.6, 1, u)
end

local function teintesLave(dm, q, Lg)
  local h = chaleur(dm, min(q, 4.39), Lg)
  local tc = REFROIDI + 1.8 * (1 - borne((330 - dm) / 400, 0, 1))
  if q < tc then
    local r, gg, b = chaleurCouleur(min(h, 1))
    return r / 255, gg / 255, b / 255, 1, h > 0.3 and 0.3 * min(1, h) or 0
  end
  local r, gg, b, a = couleurLave(q - tc + 0.25 * DUREE_FROID, DUREE_FROID)
  a = max(a, VIDAGE.plancher)
  return r, gg, b, a, 0.3 * a
end

local function poserTranche(L, pts, da, db, w, a, r, g, b)
  if db - da < 0.05 or a <= SEUIL then
    show(L, false)
    return
  end
  local xa, ya = pointSur(pts, da)
  local xb, yb = pointSur(pts, db)
  local dx, dy = xb - xa, yb - ya
  tracerVeine(L, TXVEINE, (xa + xb) / 2, (ya + yb) / 2, sqrt(dx * dx + dy * dy), w, atan2(dy, dx), a, r, g, b, false, false)
end

local function poserBout(S, R, f, e, da, db, m, rampe, q, Lg, w)
  local NT = VIDAGE.tranches
  local pts = S.lignes[f]
  local dm = (da + db) / 2
  local r, gg, b, a = teintesLave(dm, q, Lg)
  local pas = (db - da) / NT
  for j = 1, NT do
    local V = R.qv[((f - 1) * 2 + e - 1) * NT + j]
    local u = rampe == 1 and (j - 0.5) / NT or (NT - j + 0.5) / NT
    poserTranche(V, pts, da + (j - 1) * pas, da + j * pas, w, a * m * u, r * 255, gg * 255, b * 255)
  end
end

local function rendreLave(S, E)
  local R, q = S.R, E.q
  local segs = S.segs
  local Lg = 0
  if q >= 0 then Lg = (DMAX + 20) * (1 - (1 - borne(q / 0.9, 0, 1)) ^ 2) end
  if Lg <= 0 or q >= DUREE then
    cacherLave(R)
    return
  end
  local wb = S.corps
  local croit = 0.75 + 0.25 * lisse(0, 0.9, q)
  local chaud = 1 - lisse(0.9, 1.5, q)
  local uv = borne((q - VIDAGE.v0) / (VIDAGE.v1 - VIDAGE.v0), 0, 1)
  local T = S.vide * uv * uv * (3 - 2 * uv)
  local bornes = S.bornes
  local NT = VIDAGE.tranches
  local plan = {}
  local nc = #S.coulees
  for f = 1, nc do
    local B = bornes[f]
    local P
    if B then
      local tete = teteDe(q, B[2])
      local lo = max(T, B[1])
      local total = tete - lo
      if total > 0 then
        local lt = T > B[1] and min(VIDAGE.effile, T - B[1]) or 0
        local lh = min(VIDAGE.effile, tete - B[1])
        local m = 1
        if lt + lh > total then
          m = total / (lt + lh)
          lt, lh = lt * m, lh * m
        end
        P = { lo + lt, tete - lh, lo, lt, tete, lh, m }
      end
    end
    plan[f] = P or false
  end
  local tetes = {}
  local n = #segs
  for i = 1, n do
    local g = segs[i]
    local V, G, J = R.veines[i], R.lueurs[i], R.joncs[i]
    local P = plan[g.f]
    if not P or P[1] >= g.d1 or P[2] <= g.d0 or P[2] <= P[1] then
      show(V, false)
      if G then show(G, false) end
      if J then show(J, false) end
    else
      local dl = max(g.d1 - g.d0, 0.000001)
      local u0 = borne((P[1] - g.d0) / dl, 0, 1)
      local u1 = borne((P[2] - g.d0) / dl, 0, 1)
      local r, gg, b, a, ga = teintesLave((g.d0 + g.d1) / 2, q, Lg)
      local w = wb * (g.b and 0.8 or 1) * croit
      local sx, sy = g.x1 - g.x0, g.y1 - g.y0
      local dx, dy = sx * (u1 - u0), sy * (u1 - u0)
      local len = sqrt(dx * dx + dy * dy)
      local mx, my = g.x0 + sx * (u0 + u1) / 2, g.y0 + sy * (u0 + u1) / 2
      local jonc = u1 >= 1 and P[2] > g.d1
      tracerVeine(V, TXVEINE, mx, my, len, w, R.ang[i], a, r * 255, gg * 255, b * 255, g.j0 and u0 <= 0, g.j1 and jonc)
      if G then
        tracer(G, TXVLUEUR, mx, my, len, 1.8 * w, R.ang[i], len + 3.6 * w, ga, r * 255, gg * 255, b * 255)
      end
      local suivant = segs[i + 1]
      if J and jonc and suivant and suivant.f == g.f then
        local t = abs(atan2(sin(R.ang[i + 1] - R.ang[i]), cos(R.ang[i + 1] - R.ang[i])))
        if t > ANGLE_JONC then
          disque(J, g.x1, g.y1, 1.1 * w, a, r * 255, gg * 255, b * 255)
        else
          show(J, false)
        end
      elseif J then
        show(J, false)
      end
    end
  end
  for f = 1, max(nc, #R.fronts) do
    local P = plan[f]
    local B = bornes[f]
    local D = R.fronts[f]
    if P then
      local wf = wb * (B[3] and 0.8 or 1) * croit
      poserBout(S, R, f, 1, P[3], P[3] + P[4], P[7], 1, q, Lg, wf)
      poserBout(S, R, f, 2, P[5] - P[6], P[5], P[7], 2, q, Lg, wf)
      if D then
        local x, y = pointSur(S.lignes[f], P[5])
        disque(D, x, y, 1.6 * wf, 0.8 * (1 - borne((Lg - B[2]) / 40, 0, 1)) * chaud, LAVE[1], LAVE[2], LAVE[3])
      end
    else
      if D then show(D, false) end
      if f <= nc then
        for e = 1, 2 do
          for j = 1, NT do show(R.qv[((f - 1) * 2 + e - 1) * NT + j], false) end
        end
      end
    end
  end
end

local function rendreVeines(S, E)
  if S.segs then rendreLave(S, E) else veinesRepli(S, E) end
end

local function rendrePlaques(S, E)
  local R, q = S.R, E.q
  for k = 1, #PLAQUES do
    local P = PLAQUES[k]
    local kk = k - 1
    local lift = lisse(1.95 + 0.025 * kk, 2.45, q) * (1 - lisse(2.51, 2.53, q))
    local rv2 = lisse(4.6 + 0.04 * kk, 5.3 + 0.04 * kk, q)
    local rva = rv2 * (1 - lisse(6.2, 6.6, q))
    local al = lift + rva
    local corps, chaud, halo = R.pcorps[k], R.pchaud[k], R.phalo[k]
    if al > 0.002 then
      local sc = q < 4 and 1 or 0.6 + 0.4 * rv2
      local sy = 1 - 0.3 * lift
      local lev = 4 * lift
      local ch = lift + 0.5 * rva * (1 - lisse(5.4, 6.0, q))
      if ch > 0.01 then
        local r, g, b = chaleurCouleur(0.6 + 0.5 * ch)
        tracer(chaud, PCELL[k], P.hx, P.hy + 3 - lev, 64 * sc * 1.12, 64 * sc * sy * 1.12, 0, 64 * sc * sy * 1.12, ch * al, r, g, b)
        disque(halo, P.hx, P.hy + 3, 68, 0.6 * ch * al, VIVE[1], VIVE[2], VIVE[3])
      else
        show(chaud, false)
        show(halo, false)
      end
      tracer(corps, PCELL[k], P.hx, P.hy - lev, 64 * sc, 64 * sc * sy, 0, 64 * sc * sy, al)
    else
      show(corps, false)
      show(chaud, false)
      show(halo, false)
    end
  end
end

local function rendreCouronne(S, E)
  local R, q = S.R, E.q
  local sc = E.S
  local r, g, b = chaleurCouleur(E.hbed)
  disque(R.failles, CX, CY, 256 * sc, 1, r, g, b)
  local lueurF = (0.12 + 0.3 * E.sillon) * min(1, E.hbed)
  for i = 1, #FAILLES do
    local F = FAILLES[i]
    disque(R.fhalos[i], CX + sc * F.x, CY + sc * F.y, (F.br and 44 or 26) * sc, lueurF, VIVE[1], VIVE[2], VIVE[3])
  end
  local rr, rg, rb = melange(BRAISE, VIVE, 0.6)
  for k = 1, #BLOCS do
    local B = BLOCS[k]
    local vol = R.vols[k]
    local sb = vol and phaseBloc(vol, q) or 0
    local x, y = CX + sc * B.cx, CY + sc * B.cy
    if sb > 0 then
      show(R.blocs[k], false)
      show(R.roches[k], false)
      disque(R.empl[k], x, y, 128 * sc, min(1, 6 * sb), r, g, b)
    else
      if vol then show(R.empl[k], false) end
      disque(R.blocs[k], x, y, 128 * sc, 1)
      disque(R.roches[k], x, y, 128 * sc, 0.62 * E.roche, rr, rg, rb)
    end
  end
  local hs = 0.5 + 0.65 * E.sillon + 0.5 * E.eru
  local aR = 0.55 * E.respire
  local as = aR + (1 - aR) * E.sillon
  local hr, hg, hb = chaleurCouleur(hs)
  disque(R.rainures, CX, CY, 256 * sc, as, hr, hg, hb)
  disque(R.rainlueur, CX, CY, 256 * sc, 0.16 * E.respire + 0.4 * E.sillon + 0.35 * E.bronze, hr, hg, hb)
  if E.debord > 0.002 and E.prog > 0.01 then
    local cr, cg, cb = chaleurCouleur(min(1.3, 0.55 + 0.65 * E.sillon + 0.3 * E.eru))
    for i = 1, 3 do
      local c = COULEES[i]
      local Lt = c.L * E.prog
      local rm = 78 + Lt / 2
      tracer(R.langues[i], TXLANGUE, CX + sc * rm * cos(c.a), CY + sc * rm * sin(c.a), sc * Lt, sc * 2.4 * c.w, c.a, sc * (Lt + 2.4 * c.w), E.debord, cr, cg, cb)
    end
  else
    cacher(R.langues)
  end
  if E.puitsA > 0.002 and E.rw > 0.5 then
    local rw, a = E.rw, E.puitsA
    local br = E.br
    disque(R.puits[1], CX, CY, 2 * rw * sc, a, BRAISE[1], BRAISE[2], BRAISE[3])
    local c1, c2, c3 = melange(SOMBRE, VIVE, borne(br, 0, 1))
    disque(R.puits[2], CX, CY, 1.6 * rw * sc, a, c1, c2, c3)
    c1, c2, c3 = melange(SOMBRE, LAVE, borne(br, 0, 1))
    disque(R.puits[3], CX, CY, 0.8 * rw * sc, a, c1, c2, c3)
    c1, c2, c3 = melange(SOMBRE, FUSION, borne(br, 0, 1))
    disque(R.puits[4], CX, CY, 0.4 * rw * sc, a, c1, c2, c3)
    disque(R.puits[5], CX, CY, 2.6 * rw * sc, 0.45 * a * br, VIVE[1], VIVE[2], VIVE[3])
  else
    cacher(R.puits)
  end
  if E.bul > 0.002 and E.rw > 1 then
    for i = 1, #BULLES do
      local p = BULLES[i]
      local a = frac(q / p.p + p.ph)
      disque(R.bulles[i], CX + p.x * E.rw / 70, CY + p.y * E.rw / 70, 2 * (1.2 + 4.5 * a), E.bul * sin(PI * a), FUSION[1], FUSION[2], FUSION[3])
    end
  else
    cacher(R.bulles)
  end
end

local function rendreFlammes(S, E)
  local R, q = S.R, E.q
  if E.flam <= 0.002 then
    cacher(R.fl1)
    cacher(R.fl2)
    show(R.flhalo, false)
    return
  end
  local sc = E.S
  disque(R.flhalo, CX, CY, 400 * sc, 0.35 * E.flam, VIVE[1], VIVE[2], VIVE[3])
  local L0 = 0.6 + 0.4 * lisse(3.05, 3.6, q)
  for i = 1, #PICS do
    local A, B = R.fl1[i], R.fl2[i]
    if A then
      local p = PICS[i]
      local vol = R.vols[p.b + 1]
      local w = 1
      if vol then
        w = 1 - lisse(0, 0.05, phaseBloc(vol, q))
      end
      local a = E.flam * w
      if a > 0.002 then
        local dn = p.an + 0.12 * sin(7 * q + p.ph)
        local L = p.L * (0.8 + 0.2 * sin(9 * q + p.ph)) * L0
        local sw = 4 * sin(11 * q + p.ph)
        local ang = dn + atan2(sw, L)
        local x, y = CX + sc * p.x, CY + sc * p.y
        local c, s = cos(ang), sin(ang)
        local l1, w1 = 1.3 * L * sc, 14 * sc
        tracer(A, TXFLAMME, x + c * l1 / 2, y + s * l1 / 2, l1, w1, ang, l1 + w1, 0.75 * a, VIVE[1], VIVE[2], VIVE[3])
        local l2, w2 = 0.8 * L * sc, 7.7 * sc
        tracer(B, TXFLAMME, x + c * l2 / 2, y + s * l2 / 2, l2, w2, ang, l2 + w2, 0.9 * a, LAVE[1], LAVE[2], LAVE[3])
      else
        show(A, false)
        show(B, false)
      end
    end
  end
end

local function regler(S, fs, c, taille, dy, r, g, b, a)
  if S.police then
    local z = floor(taille * 2 + 0.5) / 2
    if c.z ~= z then
      c.z = z
      fs:SetFont(S.police, z, S.drap)
    end
  end
  if c.dy == nil or abs(c.dy - dy) >= 0.05 then
    c.dy = dy
    fs:SetPoint(S.ap, S.arel, S.arp, S.ax, S.ay - dy)
  end
  if c.r == nil or abs(c.r - r) >= 0.0039 or abs(c.g - g) >= 0.0039 or abs(c.b - b) >= 0.0039 then
    c.r, c.g, c.b = r, g, b
    fs:SetTextColor(r, g, b, S.ca or 1)
  end
  if c.a == nil or abs(c.a - a) >= 0.005 then
    c.a = a
    fs:SetAlpha(a)
  end
end

local function rendreNombre(S, E)
  local r, g, b = nombreCouleur(E.numK)
  r, g, b = r / 255, g / 255, b / 255
  local taille = (S.taille or 20) * E.numS
  local dy = 10 * E.numM * S.K
  local a = borne(E.numA, 0, 1)
  if E.avant then
    if S.cacheC.a ~= 0 then
      S.cacheC.a = 0
      S.count:SetAlpha(0)
    end
    if not S.copieOn then
      S.copieOn = true
      S.copie:Show()
    end
    regler(S, S.copie, S.cacheK, taille, dy, r, g, b, a)
  else
    if S.copieOn then
      S.copieOn = false
      S.copie:Hide()
    end
    regler(S, S.count, S.cacheC, taille, dy, r, g, b, a)
  end
end

local function rendreBoule(S, E)
  local R = S.R
  if E.fbA <= 0.002 then
    cacher(R.lobes)
    show(R.bhalo, false)
    return
  end
  local fbR, fbD, q = E.fbR, E.fbD, E.q
  disque(R.bhalo, CX, CY, 2.6 * fbR, 0.5 * E.fbA * (1 - fbD), VIVE[1], VIVE[2], VIVE[3])
  local K = #LOBES
  local hw = PI / K * (1.06 - 0.75 * fbD)
  for k = 1, K do
    local l = LOBES[k]
    local th = (k - 1) * TAU / K + 0.15 * q
    local rin = E.fbH * (1 - 0.3 * l.rk2 * fbD)
    local ro = fbR * (1 + 0.06 * sin(5 * th + 11 * q + l.ph) + fbD * l.rk * 0.9)
    if ro > PLAFOND then ro = max(PLAFOND, rin + 1) end
    local Lt = ro - rin
    if rin >= PLAFOND or Lt < 0.05 then
      show(R.lobes[k], false)
    else
      local rm = (rin + ro) / 2
      local Wt = 2 * hw * ro * 1.17
      local r, g, b = degrade(borne(rm / (1.5 * fbR), 0, 1))
      tracer(R.lobes[k], TXLOBE, CX + rm * cos(th), CY + rm * sin(th), Lt, Wt, th, Lt + Wt, E.fbA, r, g, b)
    end
  end
end

local function rendreTunnel(S, E)
  local R, q = S.R, E.q
  for i = 1, #FILETS do
    local p = FILETS[i]
    local a = q - p.b
    local L = R.filets[i]
    local ok = false
    if a > 0 and a < p.vie then
      local s = a / p.vie
      local rH = 22 * exp(4.3 * s)
      if rH * 0.6 <= 420 then
        local r0, r1 = rH * 0.6, rH
        local w = min(12, 0.6 + 0.02 * rH)
        if r1 > PLAFOND then r1 = max(PLAFOND, r0 + 1) end
        local op = 0.9 * lisse(0, 0.12, s) * (1 - lisse(0.8, 1, s))
        local r, g, b = chaleurCouleur(1.25 - 0.55 * s)
        local rm = (r0 + r1) / 2
        local Lt = r1 - r0 + w
        tracer(L, TXFILET, CX + rm * cos(p.ang), CY + rm * sin(p.ang), Lt, w, p.ang, Lt + w, op, r, g, b)
        ok = true
      end
    end
    if not ok then show(L, false) end
  end
  for k = 1, 3 do
    local u = (q - ONDES[k][1]) / 0.6
    if u > 0 and u < 1 then
      local rO = 84 / (1 - 0.86 * u)
      local w = 1.5 + 0.035 * rO
      local a = lisse(0, 0.05, u) * (1 - lisse(0.55, 1, u))
      local c = ONDES[k][2]
      disque(R.ondes[k], CX, CY, 2 * rO + w, 0.9 * a, c[1], c[2], c[3])
      disque(R.ondeh[k], CX, CY, 2 * rO + 2.4 * w, 0.3 * a, VIVE[1], VIVE[2], VIVE[3])
    else
      show(R.ondes[k], false)
      show(R.ondeh[k], false)
    end
  end
end

local function volanteBloc(S, k, x, y, sc, rot, a, chaud)
  local V = S.R.vbl[k]
  tracer(V.c, TXBLOC, x, y, 128 * sc, 128 * sc, rot, 128 * sc, a)
  tracer(V.o, TXBLOC, x, y, 128 * sc, 128 * sc, rot, 128 * sc, 0.4 * chaud * a, VIVE[1], VIVE[2], VIVE[3])
  disque(V.h, x, y, 80 * sc, 0.5 * a * chaud, VIVE[1], VIVE[2], VIVE[3])
end

local function rendreVolantes(S, E)
  local R, q = S.R, E.q
  for i = 1, #VOL do
    local p = VOL[i]
    local a = q - p.b
    local V = R.vol[i]
    if a > 0 and a < p.vie then
      local sv = a / p.vie
      local z = 1 - (1 - 1 / p.m) * sv
      local rr = p.r0 / z
      local alv = (p.flou and 0.55 or 1) * lisse(0, 0.04, a) * (1 - lisse(0.65, 1, sv))
      local x, y = CX + rr * cos(p.ang), CY + rr * sin(p.ang)
      local sc = p.s0 / z
      local rot = p.spin * sv
      if p.flou then
        local cell = PCELL[V.cell]
        local f1, f2, f3 = 1.3 * sc, 1.12 * sc, 0.95 * sc
        tracer(V[1], PCELL[V.cell], x, y, 64 * f1, 64 * f1, rot, 46 * f1, alv * 0.22, BRAISE[1], BRAISE[2], BRAISE[3])
        tracer(V[2], cell, x, y, 64 * f2, 64 * f2, rot, 46 * f2, alv * 0.35)
        tracer(V[3], cell, x, y, 64 * f3, 64 * f3, rot, 46 * f3, alv * 0.55)
      else
        tracer(V[1], PCELL[i], x, y, 64 * sc, 64 * sc, rot, 46 * sc, alv)
      end
    else
      for j = 1, #V do show(V[j], false) end
    end
  end
  for k = 1, #BLOCS do
    local vol = R.vols[k]
    if vol then
      local B = BLOCS[k]
      local sb = phaseBloc(vol, q)
      local a = 1 - lisse(0.7, 1, sb)
      local V = R.vbl[k]
      if sb > 0 and a > 0.002 then
        local z = 1 - (1 - 1 / vol.m) * sb
        volanteBloc(S, k, CX + E.S * B.cx / z, CY + E.S * B.cy / z, E.S / z, vol.spin * sb, a, 1 - 0.5 * sb)
      else
        show(V.c, false)
        show(V.o, false)
        show(V.h, false)
      end
    end
  end
end

local function rendreBombes(S, E)
  local R, q = S.R, E.q
  for i = 1, #BOMBES do
    local p = BOMBES[i]
    local a = q - p.b
    local B = R.bombes[i]
    if a > 0 and a < p.vie then
      local sv = a / p.vie
      local z = 1 - (1 - 1 / p.m) * sv
      local z2 = 1 - (1 - 1 / p.m) * max(0, sv - 0.12)
      local rb, rt = p.r0 / z, p.r0 / z2
      local cb, sb = cos(p.ang), sin(p.ang)
      local x, y, x0, y0 = CX + rb * cb, CY + rb * sb, CX + rt * cb, CY + rt * sb
      local r = p.r / z
      local op = lisse(0, 0.04, a) * (1 - lisse(0.75, 1, sv))
      local h = 1.4 - 0.6 * sv
      local dx, dy = x - x0, y - y0
      local len = sqrt(dx * dx + dy * dy)
      local th = len > 0.05 and atan2(dy, dx) or p.ang
      local cr, cg, cbl = chaleurCouleur(h)
      tracer(B.c, TXCOMETE, (x + x0) / 2, (y + y0) / 2, len + 2 * r, 2 * r, th, len + 4 * r, op, cr, cg, cbl)
      disque(B.h, x, y, 6.4 * r, 0.7 * op, VIVE[1], VIVE[2], VIVE[3])
    else
      show(B.c, false)
      show(B.h, false)
    end
  end
end

local function rendreParticules(S, E)
  local R, q = S.R, E.q
  for i = 1, #PLUIE do
    local p = PLUIE[i]
    local a = q - p.b
    local L = R.pluie[i]
    if a > 0 and a < p.vie then
      local op = lisse(0, 0.2, a) * (1 - lisse(p.vie * 0.6, p.vie, a))
      local r, g, b = chaleurCouleur(1.1 - 0.6 * a / p.vie)
      disque(L, p.x + p.sw * sin(2 * a + p.ph), p.y + p.vy * a + 20 * a * a, 6.4 * p.r, op, r, g, b)
    else
      show(L, false)
    end
  end
  for i = 1, #GRAVATS do
    local p = GRAVATS[i]
    local a = q - p.b
    local L = R.gravats[i]
    if a > 0 and a < p.vie then
      local op = lisse(0, 0.08, a) * (1 - lisse(0.6 * p.vie, p.vie, a))
      disque(L, p.x + p.vx * a, p.y + p.vy * a + 130 * a * a, p.s, 0.8 * op, POUSSIERE[1], POUSSIERE[2], POUSSIERE[3])
    else
      show(L, false)
    end
  end
  for i = 1, #VAPEURS do
    local p = VAPEURS[i]
    local a = q - p.b
    local L = R.vapeurs[i]
    if a > 0 and a < p.vie then
      local u = a / p.vie
      disque(L, p.x, p.y - 36 * u, 2 * (6 + 22 * u), 0.32 * sin(PI * u), VAPEUR[1], VAPEUR[2], VAPEUR[3])
    else
      show(L, false)
    end
  end
  local sc = E.S
  for i = 1, #GOUTTES do
    local p = GOUTTES[i]
    local a = q - p.b
    local L = R.gouttes[i]
    if a > 0 and a < 0.6 then
      local op = lisse(0, 0.05, a) * (1 - lisse(0.35, 0.6, a))
      local gs = 0.75 * sc
      tracer(L, TXGOUTTE, CX + sc * p.x, CY + sc * (26 + 180 * a * a) - 14 * gs, 56 * gs, 16 * gs, PI / 2, 72 * gs, op, LAVE[1], LAVE[2], LAVE[3])
    else
      show(L, false)
    end
  end
end

local function rendreVitre(S, E)
  local R, q = S.R, E.q
  for i = 1, #SPLATS do
    local p = SPLATS[i]
    local a = q - p.b
    local V = R.vitre[i]
    if a > 0 and a < 0.62 then
      local imp = facile(a / 0.06)
      local op = 1 - lisse(0.32, 0.62, a)
      local h = 1.35 - 1.05 * lisse(0.04, 0.5, a)
      local Lc = p.coule * lisse(0.05, 0.45, a)
      disque(V.h, p.x, p.y + 0.5 * Lc, 5.2 * p.r, 0.45 * op * min(1, h), VIVE[1], VIVE[2], VIVE[3])
      local r, g, b = chaleurCouleur(h)
      disque(V.c, p.x, p.y, 128 * imp, op, r, g, b)
      local r2, g2, b2 = chaleurCouleur(h + 0.25)
      disque(V.k, p.x, p.y, 128 * imp * 0.45, op * lisse(0.6, 1.2, h), r2, g2, b2)
    else
      show(V.h, false)
      show(V.c, false)
      show(V.k, false)
    end
  end
end

local function rendreEffets(S, E)
  local R = S.R
  if E.q >= 2.5 then
    disque(R.fxlueur, CX, CY, SCENE, 0.9 * E.eru, LAVE[1], LAVE[2], LAVE[3])
    disque(R.fxvign, CX, CY, SCENE, 0.75 * E.vign, ORANGE[1], ORANGE[2], ORANGE[3])
    disque(R.fxflash, CX, CY, 1.5 * SCENE, 0.85 * E.flash, FUSION[1], FUSION[2], FUSION[3])
  else
    show(R.fxlueur, false)
    show(R.fxvign, false)
    show(R.fxflash, false)
  end
end

local function rendreBraises(S, E)
  local R, t = S.R, E.t
  for i = 1, #BRAISES do
    local p = BRAISES[i]
    local a = frac(t / p.P + p.ph)
    disque(R.braises[i], p.x + p.sw * sin(TAU * a * 1.5 + p.ph * 6), 545 - 420 * a, 7 * p.r, 0.6 * sin(PI * a), VIVE[1], VIVE[2], VIVE[3])
  end
end

local function trembler(S, sx, sy)
  local x, y = sx * S.K, -sy * S.K
  if S.tx == nil or abs(S.tx - x) >= 0.01 or abs(S.ty - y) >= 0.01 then
    S.tx, S.ty = x, y
    for i = 1, #S.cadres do
      S.cadres[i]:SetPoint("CENTER", S.ring, "CENTER", x, y)
    end
  end
end

local function rendre(S, t, q)
  local E = S.E
  etat(E, t, q)
  trembler(S, E.sx, E.sy)
  rendreFond(S, E)
  rendreVeines(S, E)
  rendrePlaques(S, E)
  rendreCouronne(S, E)
  rendreFlammes(S, E)
  rendreBoule(S, E)
  rendreTunnel(S, E)
  rendreVolantes(S, E)
  rendreBombes(S, E)
  rendreParticules(S, E)
  rendreVitre(S, E)
  rendreEffets(S, E)
  rendreBraises(S, E)
end

local function construire(S, ring, W)
  local K = W / DIAMETRE
  local niveaux = {}
  for i = 1, 15 do niveaux[i] = cadre(ring, i, SCENE * K) end
  local fDalle, fSocle, fVeines, fPlaques, fCour, fFlam, fNombre, fBoule, fTunnel, fVol, fBomb, fPart, fVitre, fFx, fBraise =
    niveaux[1], niveaux[2], niveaux[3], niveaux[4], niveaux[5], niveaux[6], niveaux[7], niveaux[8], niveaux[9], niveaux[10], niveaux[11], niveaux[12], niveaux[13], niveaux[14], niveaux[15]
  S.fNombre = fNombre
  S.cadres = {}
  for i = 2, 15 do S.cadres[#S.cadres + 1] = niveaux[i] end
  S.K = K
  local R = {}
  S.R = R
  local dalle = creer(fDalle, K, "dalle", "BLEND", nil)
  dalle.t:SetDrawLayer("BACKGROUND")
  pose(dalle, CX, CY, DALLE, DALLE)
  opacite(dalle, 1)
  R.amb = creer(fDalle, K, "halo", "ADD", nil)
  R.ciel = creer(fDalle, K, "halo", "ADD", nil)
  R.socle = creer(fSocle, K, "socle", "BLEND", nil)
  pose(R.socle, CX, CY, 256, 256)
  opacite(R.socle, 1)

  R.ang = {}
  R.veines = lot(fVeines, K, "veine", "BLEND", max(#SEGS, JOINTS and POOL or 0), nil)
  R.lueurs = {}
  for i = 1, #R.veines do
    if i <= #SEGS then R.ang[i] = atan2(SEGS[i].y1 - SEGS[i].y0, SEGS[i].x1 - SEGS[i].x0) end
    if (i <= #SEGS and not SEGS[i].b) or (JOINTS and i <= POOL / 2) then R.lueurs[i] = creer(fVeines, K, "veine-lueur", "ADD", nil) end
  end
  R.angRepli = R.ang
  R.joncs = JOINTS and lot(fVeines, K, "point", "BLEND", POOL, nil) or {}
  R.fronts = JOINTS and lot(fVeines, K, "point", "ADD", NFRONTS, nil) or {}

  R.pchaud, R.pcorps, R.phalo = {}, {}, {}
  for k = 1, #PLAQUES do
    R.phalo[k] = creer(fPlaques, K, "halo", "ADD", nil)
    R.pchaud[k] = creer(fPlaques, K, "plaques-chaud", "BLEND", nil)
    R.pcorps[k] = creer(fPlaques, K, "plaques", "BLEND", nil)
  end

  R.failles = creer(fCour, K, "failles", "BLEND", nil)
  R.fhalos = lot(fCour, K, "halo", "ADD", #FAILLES, nil)
  R.vols = {}
  for i = 1, #DETACHES do
    local n = i - 1
    R.vols[DETACHES[i] + 1] = { b = 2.56 + 0.04 * n, vie = 0.45, m = 7, spin = (n % 2 == 1 and 1 or -1) * 1.2, rs = 4.7 + 0.12 * n, re = 5.3 + 0.12 * n }
  end
  R.blocs, R.roches, R.empl = {}, {}, {}
  for k = 1, #BLOCS do
    R.blocs[k] = creer(fCour, K, "bloc-" .. k, "BLEND", nil)
    R.roches[k] = creer(fCour, K, "bloc-roche-" .. k, "ADD", nil)
    if R.vols[k] then R.empl[k] = creer(fCour, K, "bloc-roche-" .. k, "BLEND", nil) end
  end
  R.rainures = creer(fCour, K, "rainures", "BLEND", nil)
  R.rainlueur = creer(fCour, K, "rainures-lueur", "ADD", nil)
  R.langues = lot(fCour, K, "langue", "BLEND", 3, nil)
  R.puits = {}
  for i = 1, 4 do R.puits[i] = creer(fCour, K, "point", "BLEND", nil) end
  R.puits[5] = creer(fCour, K, "halo", "ADD", nil)
  R.bulles = lot(fCour, K, "bulle", "ADD", #BULLES, nil)

  R.flhalo = creer(fFlam, K, "halo", "ADD", nil)
  R.fl1, R.fl2 = {}, {}
  for i = 1, #PICS do
    if not R.vols[PICS[i].b + 1] then
      R.fl1[i] = creer(fFlam, K, "flamme", "ADD", nil)
      R.fl2[i] = creer(fFlam, K, "flamme", "ADD", nil)
    end
  end

  local copie = fNombre:CreateFontString(nil, "OVERLAY")
  S.copie = copie
  R.bhalo = creer(fBoule, K, "halo", "ADD", nil)
  R.lobes = lot(fBoule, K, "lobe", "ADD", #LOBES, nil)

  R.filets = lot(fTunnel, K, "filet", "ADD", #FILETS, nil)
  R.ondes = lot(fTunnel, K, "anneau", "ADD", 3, nil)
  R.ondeh = lot(fTunnel, K, "anneau-halo", "ADD", 3, nil)

  R.vol, R.vbl = {}, {}
  for i = 1, #VOL do
    if VOL[i].flou then
      local V = { cell = 4 + 4 * (i - 17) }
      V[1] = creer(fVol, K, "plaques-chaud", "BLEND", nil)
      V[2] = creer(fVol, K, "plaques", "BLEND", nil)
      V[3] = creer(fVol, K, "plaques", "BLEND", nil)
      R.vol[i] = V
    else
      R.vol[i] = { creer(fVol, K, "plaques", "BLEND", nil) }
    end
  end
  for k = 1, #BLOCS do
    if R.vols[k] then
      R.vbl[k] = { h = creer(fVol, K, "halo", "ADD", nil), c = creer(fVol, K, "bloc-" .. k, "BLEND", nil), o = creer(fVol, K, "bloc-roche-" .. k, "ADD", nil) }
    end
  end

  R.bombes = {}
  for i = 1, #BOMBES do
    R.bombes[i] = { h = creer(fBomb, K, "halo", "ADD", nil), c = creer(fBomb, K, "comete", "ADD", nil) }
  end

  R.pluie = lot(fPart, K, "braise", "ADD", #PLUIE, nil)
  R.gravats = lot(fPart, K, "aplat", "BLEND", #GRAVATS, nil)
  R.vapeurs = lot(fPart, K, "vapeur", "BLEND", #VAPEURS, nil)
  R.gouttes = lot(fPart, K, "goutte", "ADD", #GOUTTES, nil)

  R.vitre = {}
  for i = 1, #SPLATS do
    R.vitre[i] = { h = creer(fVitre, K, "halo", "ADD", nil), c = creer(fVitre, K, "vitre-" .. i, "BLEND", nil), k = creer(fVitre, K, "vitre-" .. i, "ADD", nil) }
  end

  R.fxlueur = creer(fFx, K, "halo", "ADD", nil)
  R.fxvign = creer(fFx, K, "halo", "ADD", nil)
  R.fxflash = creer(fFx, K, "halo", "ADD", nil)

  R.braises = lot(fBraise, K, "braise", "ADD", #BRAISES, nil)
end

local function fournir(S, ring, count)
  S.ring, S.count = ring, count
  S.E = {}
  viderCaches(S)
  S.police, S.taille, S.drap = count:GetFont()
  if S.police and (S.drap == nil or S.drap == "") then S.drap = "OUTLINE" end
  S.cr, S.cg, S.cb, S.ca = count:GetTextColor()
  S.ap, S.arel, S.arp, S.ax, S.ay = count:GetPoint(1)
  S.parent = count:GetParent()
  S.last = tonumber(count:GetText())
  local copie = S.copie
  if S.police then copie:SetFont(S.police, S.taille, S.drap) end
  local j = count.GetJustifyH and count:GetJustifyH()
  if j then copie:SetJustifyH(j) end
  if S.cr then copie:SetTextColor(S.cr, S.cg, S.cb, S.ca) end
  if S.ap then copie:SetPoint(S.ap, S.arel, S.arp, S.ax, S.ay) end
  copie:Hide()
  S.copieOn = false
  actualiserTrace(S)
end

local function reposNombre(S)
  if not S.sale then return end
  S.sale = false
  local count = S.count
  count:SetAlpha(1)
  if S.cr then count:SetTextColor(S.cr, S.cg, S.cb, S.ca) end
  if S.police then count:SetFont(S.police, S.taille, S.drap) end
  if S.ap then count:SetPoint(S.ap, S.arel, S.arp, S.ax, S.ay) end
  S.copie:Hide()
  S.copieOn = false
  viderCaches(S)
end

local function restaurer(S)
  reposNombre(S)
  if S.count:GetParent() ~= S.parent then S.count:SetParent(S.parent) end
end

local function build(ring, count)
  if not ring or not count then return end
  if ring.ebonapiCoeur then return end
  local W = ring:GetWidth()
  if not W or W <= 0 then return end
  local S = { mode = "repos", tau = 0, acc = 0, t = T_REPOS, actif = false, sale = false }
  ring.ebonapiCoeur = S
  construire(S, ring, W)
  fournir(S, ring, count)

  local function repos()
    S.mode = "repos"
    S.acc = 0
    reposNombre(S)
    rendre(S, S.t, -1)
  end

  local function image()
    rendre(S, S.t, S.tau)
    rendreNombre(S, S.E)
    S.sale = true
  end

  local function surMiseAJour(_, ecoule)
    if ecoule > 0.05 then ecoule = 0.05 end
    S.acc = S.acc + ecoule
    local sequence = S.mode == "sequence"
    if S.acc < (sequence and STEP or PAS_REPOS) - 1e-9 then return end
    local pas = S.acc
    S.acc = 0
    S.t = S.t + pas
    if not sequence then
      rendre(S, S.t, -1)
    else
      S.tau = S.tau + pas
      if S.cleTrace == "repli" and not S.verifie then
        if S.tau < 1 then
          actualiserTrace(S)
        else
          S.verifie = true
          S.cleTrace = nil
          actualiserTrace(S, true)
        end
      end
      if S.tau >= DUREE + 1e-6 then
        repos()
      else
        image()
      end
    end
  end

  local function demarrer(precedent)
    S.mode = "sequence"
    S.tau = 0
    S.acc = 0
    S.verifie = false
    viderCaches(S)
    actualiserTrace(S)
    S.copie:SetText(tostring(precedent))
    if S.count:GetParent() ~= S.fNombre then S.count:SetParent(S.fNombre) end
    image()
    if not S.actif then
      S.actif = true
      ring:SetScript("OnUpdate", surMiseAJour)
    end
  end

  repos()

  ring:HookScript("OnHide", function()
    if S.actif then
      S.actif = false
      ring:SetScript("OnUpdate", nil)
    end
    if S.mode == "sequence" then repos() end
    restaurer(S)
  end)

  ring:HookScript("OnShow", function()
    demarrer(count:GetText() or "")
  end)

  if hooksecurefunc then
    hooksecurefunc(count, "SetText", function(_, texte)
      local nombre = tonumber(texte)
      if not nombre then return end
      local avant = S.last
      S.last = nombre
      if avant and nombre > avant and S.mode == "repos" and ring:IsVisible() then
        demarrer(avant)
      end
    end)
  end

  if ring:IsVisible() then
    demarrer(count:GetText() or "")
  end
end

EbonAPI.PrestigeAnimations.coeur = function(ring, countText)
  build(ring, countText)
end
